UPDATE sys_menu
SET delete_flag = id, deleted_at = #{deletedAt}
WHERE id IN

    #{id}

AND delete_flag = 0 AND tenant_id = #{tenantId}

mapper.select:
WITH RECURSIVE starting_points AS ( SELECT id AS root_id FROM sys_menu WHERE id IN
#{menuId}
AND tenant_id = #{tenantId} AND delete_flag = 0 ), descendants AS ( SELECT sp.root_id, m.id AS descendant_id, m.parent_id FROM sys_menu m INNER JOIN starting_points sp ON m.id = sp.root_id WHERE m.tenant_id = #{tenantId} AND m.delete_flag = 0 UNION ALL SELECT d.root_id, m.id AS descendant_id, m.parent_id FROM sys_menu m INNER JOIN descendants d ON m.parent_id = d.descendant_id WHERE m.tenant_id = #{tenantId} AND m.delete_flag = 0 ) SELECT root_id AS menuId, descendant_id AS descendantId FROM descendants
